package bowling

import "errors"

// Game tracks the rolls of a bowling game and can score it once complete.
type Game struct {
	rolls      []int // every accepted roll, in order
	frame      int   // 0-based index of the frame currently being played
	frameRolls []int // rolls made in the current frame
	done       bool  // true once the tenth frame is finished
}

var (
	errNegativeRoll   = errors.New("Negative roll is invalid")
	errTooManyPins    = errors.New("Pin count exceeds pins on the lane")
	errGameIsOver     = errors.New("Cannot roll after game is over")
	errGameIncomplete = errors.New("Score cannot be taken until the end of the game")
)

// NewGame returns a Game ready to accept rolls.
func NewGame() *Game {
	return &Game{}
}

// Roll records a throw of the ball that knocks down pins pins.
// It returns an error if the roll is illegal or the game is already over.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 {
		return errTooManyPins
	}
	if g.done {
		return errGameIsOver
	}
	if err := g.rollLegal(pins); err != nil {
		return err
	}

	g.rolls = append(g.rolls, pins)
	g.frameRolls = append(g.frameRolls, pins)

	if g.frameComplete() {
		g.frameRolls = nil
		g.frame++
		if g.frame == 10 {
			g.done = true
		}
	}
	return nil
}

// rollLegal reports whether a roll of pins is legal given the current frame state.
func (g *Game) rollLegal(pins int) error {
	n := len(g.frameRolls)
	if n == 0 {
		return nil // fresh lane
	}
	first := g.frameRolls[0]
	if n == 1 {
		// A fill ball after a strike in the tenth frame is thrown at a fresh lane.
		if g.frame == 9 && first == 10 {
			return nil
		}
		if first+pins > 10 {
			return errTooManyPins
		}
		return nil
	}
	// n == 2 only occurs in the tenth frame, where a strike or spare earns
	// fill balls. The second fill ball after a non-strike first fill ball is
	// thrown at the pins left standing by it.
	if first == 10 && g.frameRolls[1] != 10 && g.frameRolls[1]+pins > 10 {
		return errTooManyPins
	}
	return nil
}

// frameComplete reports whether the current frame is finished.
func (g *Game) frameComplete() bool {
	n := len(g.frameRolls)
	if n == 0 {
		return false
	}
	first := g.frameRolls[0]
	if g.frame < 9 {
		if first == 10 {
			return true // strike
		}
		return n == 2 && first+g.frameRolls[1] == 10 // spare
	}
	// Tenth frame: a strike earns two fill balls, a spare earns one, and an
	// open frame ends the game.
	switch n {
	case 1:
		return false
	case 2:
		if first == 10 {
			return false
		}
		return first+g.frameRolls[1] < 10
	default:
		return true
	}
}

// Score returns the total score of a completed game.
func (g *Game) Score() (int, error) {
	if !g.done {
		return 0, errGameIncomplete
	}
	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case g.rolls[i] == 10: // strike: bonus of the next two rolls
			total += 10 + g.rolls[i+1] + g.rolls[i+2]
			i++
		case g.rolls[i]+g.rolls[i+1] == 10: // spare: bonus of the next roll
			total += 10 + g.rolls[i+2]
			i += 2
		default: // open frame
			total += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	return total, nil
}

